                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.horizontal_sales_categories AS ( with metafields AS ( SELECT sku_group,product_type,product_tags from snitch_db.maplemonk.metafields_data ), shopify_sales AS ( SELECT order_timestamp::date AS Date, \'Shopify\' AS type, a.sku_group, b.product_type as category, b.product_tags as product_tags, case when lower(webshopney) = \'snitch_ios\' and lower(tags) = \'snitch_ios\' then \'App2_IOS\' when lower(webshopney) = \'snitch_ios\' and lower(tags) != \'snitch_ios\' then \'App2_Android\' when lower(webshopney) = \'web\' then \'Web\' else \'App\' end as channel, SUM(NULLIF(gross_sales, 0)) AS gross_sales, SUM(NULLIF(quantity, 0)) AS gross_quantity, SUM(discount) AS discount_amount, SUM(CASE WHEN new_customer_flag != \'Repeated\' THEN gross_sales ELSE 0 END) AS new_customers_revenue, SUM(CASE WHEN new_customer_flag = \'Repeated\' THEN gross_sales ELSE 0 END) AS repeat_customers_revenue, COUNT(DISTINCT CASE WHEN new_customer_flag != \'Repeated\' THEN customer_id ELSE NULL END) AS new_customers FROM snitch_db.maplemonk.fact_items_snitch a left join metafields b on a.sku_group = b.sku_group WHERE LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%influ%\' AND order_name NOT IN (\'2431093\',\'2422140\',\'2425364\',\'2430652\',\'2422237\',\'2420623\',\'2429832\',\'2422378\',\'2428311\',\'2429064\',\'2428204\',\'2421343\',\'2431206\',\'2430491\',\'2426682\',\'2426487\',\'2426458\',\'2423575\',\'2422431\',\'2423612\',\'2426625\',\'2428117\',\'2426894\',\'2425461\',\'2426570\',\'2423455\',\'2430777\',\'2426009\',\'2428245\',\'2427269\',\'2430946\',\'2425821\',\'2429986\',\'2429085\',\'2422047\',\'2430789\',\'2420219\',\'2428341\',\'2430444\',\'2426866\',\'2431230\',\'2425839\',\'2430980\',\'2427048\',\'2430597\',\'2420499\',\'2431050\',\'2420271\',\'2426684\',\'2428747\',\'2423523\',\'2431171\',\'2430830\',\'2425325\',\'2428414\',\'2429054\',\'2423596\') AND tags NOT IN (\'FLITS_LOGICERP\') GROUP BY 1,2,3,4,5, 6 ), sku_prices as ( select sku_group,price from snitch_db.maplemonk.availability_master_v2 ), marketplace_pre_data AS ( SELECT a.order_date AS Date, \'Marketplace\' AS type, a.sku_group, c.product_type as category, c.product_tags as product_tags, CASE WHEN a.marketplace IN (\'SNITCH VR MALL\', \'SNITCH - FOCO - VR MALL\') THEN \'Store_Vr_Mall\' WHEN a.marketplace IN (\'FLIPKART\', \'FLIPKART_SAPL\', \'FLIPKART_SAPLWH2\', \'FLIPKART_SAPL_EMIZA\', \'FLIPKART_SAPL_SR\') THEN \'Marketplace_Flipkart\' WHEN a.marketplace IN (\'SNITCH BRIGADE ROAD\', \'SNITCH - COFO - BRIGADE ROAD\',\'SNITCH - COFO - BRIGADE ROAD\') THEN \'Store_Brigade_Road\' WHEN a.marketplace IN (\'SNITCH MBH\', \'SNITCH - FOCO - MBH\') THEN \'Store_Mbh\' WHEN a.marketplace IN (\'SAPL_AJIO_OMNI_SR\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_EMIZA\', \'SAPL_AJIO_OMNI_2\', \'AJIO_OMNI\') THEN \'Marketplace_Ajio\' WHEN a.marketplace = \'SNITCH - FOCO - TRION\' THEN \'Store_Trion\' WHEN a.marketplace = \'SNITCH - FOCO - EVA\' THEN \'Store_Eva\' WHEN a.marketplace IN (\'SAPL_MYNTRA_EMIZA\', \'MYNTRAPPMP\', \'SAPL_MYNTRAPPMP_SR\', \'SAPL_MYNTRAPPMP\', \'MYNTRAPPMP_SAPL_WH2\') THEN \'Marketplace_Myntra\' WHEN a.marketplace = \'NYKAA_FASHION\' THEN \'Marketplace_Nykaa\' WHEN a.marketplace = \'SNITCH - FOCO - GANDHI NAGAR\' THEN \'Store_Gandhi_Nagar\' WHEN a.marketplace = \'SNITCH - COCO - BEL ROAD\' THEN \'Store_Bel_Road\' WHEN a.marketplace IN (\'AMAZON_FLEX_API_EMIZA\', \'AMAZON_FLEX_API_SR\', \'AMAZON_FLEX_API_SAPL\', \'AMAZON\') THEN \'Marketplace_Amazon\' WHEN a.marketplace = \'SNITCH - COCO - HSR LAYOUT\' THEN \'Store_Hsr\' WHEN a.marketplace = \'SHOPIFY\' THEN \'Shopify\' WHEN a.marketplace IN (\'SNITCH - JAYANAGAR\', \'SNITCH - COCO - JAYANAGAR\') THEN \'Store_Jayanagar\' WHEN a.marketplace = \'SNITCH - COFO - SARATH CITY\' THEN \'Store_Sarath_City\' END AS channel, SUM(NULLIF(a.selling_price, 0)) AS gross_sales, SUM(NULLIF(a.shipping_quantity, 0)) AS gross_quantity, SUM(NULLIF((b.price * a.shipping_quantity) - a.selling_price, 0)) AS discount_amount, SUM(CASE WHEN new_customer_flag != \'Repeated\' THEN selling_price ELSE 0 END) AS new_customers_revenue, SUM(CASE WHEN new_customer_flag = \'Repeated\' THEN selling_price ELSE 0 END) AS repeat_customers_revenue, COUNT(DISTINCT CASE WHEN new_customer_flag != \'Repeated\' THEN customer_id ELSE NULL END) AS new_customers FROM snitch_db.maplemonk.unicommerce_fact_items_snitch a left join sku_prices b on a.sku_group = b.sku_group left join metafields c on a.sku_group = c.sku_group GROUP BY 1, 2, 3, 4, 5, 6 ), marketplace_data AS ( SELECT * FROM marketplace_pre_data WHERE channel LIKE \'Marketplace%\' and gross_quantity is not null ), stores_data AS ( SELECT order_date AS Date, \'Store\' AS type, a.sku_group, b.product_type as category, b.product_tags as product_tags, MARKETPLACE_MAPPED AS channel, SUM(NULLIF(selling_price, 0)) AS gross_sales, SUM(NULLIF(shipping_quantity, 0)) AS gross_quantity, nullif(SUM(NULLIF(discount, 0)),0) AS discount_amount, SUM(CASE WHEN new_customer_flag != \'Repeated\' THEN selling_price ELSE 0 END) AS new_customers_revenue, SUM(CASE WHEN new_customer_flag = \'Repeated\' THEN selling_price ELSE 0 END) AS repeat_customers_revenue, COUNT(DISTINCT CASE WHEN new_customer_flag != \'Repeated\' THEN phone ELSE NULL END) AS new_customers FROM snitch_db.maplemonk.STORE_fact_items_offline a left join metafields b on a.sku_group = b.sku_group where marketplace_mapped not like \'%WH%\' GROUP BY 1, 2, 3, 4, 5, 6 ) select * from shopify_sales union select * from marketplace_data union select * from stores_data );",
